from batch07 import *
start('snooping','DHCP Snooping','5.7',['https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst4500/XE3-10-0E/configuration/guide/xe-310-cg/dhcp.html','https://www.cisco.com/c/en/us/support/docs/switches/catalyst-3750-series-switches/72846-layer2-secftrs-catl3fixed.html'])
q('Rogue DHCP','Który problem przede wszystkim ogranicza DHCP Snooping?','Odpowiedzi nieuprawnionego serwera DHCP na niezaufanym porcie',['Zmianę AD przez OSPF|AD należy do wyboru źródła tras.','Wszystkie błędne odpowiedzi DNS|DHCP Snooping nie analizuje wszystkich odpowiedzi DNS.','Każdy atak na TCP|To mechanizm związany z DHCP, nie ogólny firewall.'],'Snooping rozróżnia zaufane drogi odpowiedzi serwera i porty klientów.')
c('Proces snooping','Włącz globalnie DHCP Snooping. VLAN-y zostaną wskazane osobno.','SW(config)# ip dhcp {{b0}}',['snooping'],'Włączenie globalne jest wymagane obok aktywacji dla wybranych VLAN-ów.')
c('Chroniony VLAN','Snooping jest włączony globalnie. Obejmij nim VLAN 40.','SW(config)# ip dhcp snooping vlan {{b0}}',['40'],'Wskazanie VLAN-u ogranicza zakres działania mechanizmu.')
q('Granica zaufania DHCP','Do którego portu należy przypisać trust w prostym labie: serwer DHCP na G1/0/24, klienci na G1/0/1–10?','G1/0/24, po zweryfikowaniu serwera',['Do wszystkich portów klientów|To pozwoliłoby klientom wysyłać odpowiedzi serwera.','Tylko do portu pierwszego klienta|Pierwszeństwo klienta nie określa zaufania.','Do żadnego, także serwer ma być untrusted|Odpowiedzi serwera z niezaufanego wejścia zostaną odrzucone.'],'Zaufanie nadaje się kontrolowanej drodze do legalnego serwera, nie wszystkim uplinkom automatycznie.')
c('Zaufany serwer','Jesteś na interfejsie do zweryfikowanego serwera. Dopuść jego odpowiedzi DHCP.','SW(config-if)# ip dhcp snooping {{b0}}',['trust'],'Trust jest właściwością interfejsu i dotyczy odbieranego na nim ruchu DHCP.')
c('Baza dzierżaw snooping','Wyświetl nauczone powiązania DHCP Snooping.','SW# show ip dhcp snooping {{b0}}',['binding'],'Tabela binding zawiera m.in. powiązanie adresu IP, MAC, VLAN-u i interfejsu.')
q('Jednostka limitu','Co oznacza ip dhcp snooping limit rate 15 na obsługującym ją Catalyst?','Limit 15 pakietów DHCP na sekundę',['Limit 15 Mb/s całego portu|To nie ogranicznik przepustowości całego interfejsu.','Limit 15 adresów MAC|Liczba secure MAC należy do Port Security.','Dzierżawa na 15 minut|Długość dzierżawy ustala serwer DHCP.'],'Limit dotyczy częstości pakietów DHCP; nie jest liczbą klientów.')
c('Proces i zakres','Uruchom snooping dla VLAN-ów 10 i 20, wpisując listę w rosnącej kolejności.','SW(config)# ip dhcp {{b0}}\nSW(config)# ip dhcp snooping vlan {{b1}}',['snooping','10,20'],'Globalna aktywacja i lista VLAN-ów są oddzielnymi krokami.')
c('Zaufanie cofnięte','G1/0/5 stał się portem użytkownika. Cofnij trust i ustaw limit 20 pps.','SW(config-if)# no ip dhcp snooping {{b0}}\nSW(config-if)# ip dhcp snooping limit rate {{b1}}',['trust','20'],'Zmiana roli portu wymaga aktualizacji granicy zaufania.')
q('Adres statyczny w tabeli','Host ma ręcznie ustawione IP i nie korzystał z DHCP. Dlaczego nie ma dynamicznego wpisu snooping?','Nie nastąpiła wymiana DHCP, z której można nauczyć binding',['Każdy host statyczny jest automatycznie atakującym|Brak wpisu nie dowodzi ataku.','Snooping uczy adresy z każdego ARP|ARP nie jest źródłem dynamicznych dzierżaw DHCP.','Każdy ping tworzy dzierżawę|ICMP nie przydziela adresów DHCP.'],'Brak wpisu jest istotny dla mechanizmów korzystających z tej bazy, np. DAI.')
c('Uplink i weryfikacja','Na sprawdzonym uplinku do serwera ustaw trust, a następnie pokaż bazę binding.','SW(config-if)# ip dhcp snooping {{b0}}\nSW(config-if)# end\nSW# show ip dhcp snooping {{b1}}',['trust','binding'],'Po zmianie konfiguracji sprawdza się rzeczywiste nauczenie dzierżaw.')
c('Wyłącz jeden VLAN','Wyłącz snooping tylko w VLAN 30 i pokaż stan całej funkcji.','SW(config)# no ip dhcp snooping vlan {{b0}}\nSW(config)# end\nSW# show ip dhcp {{b1}}',['30','snooping'],'Usunięcie VLAN-u z zakresu nie wyłącza funkcji globalnie.')
q('Brak DHCP po wdrożeniu','Klienci przestali dostawać adresy tuż po włączeniu snooping. Legalne OFFER wracają uplinkiem oznaczonym untrusted. Co naprawić?','Zweryfikować uplink i nadać mu właściwe zaufanie',['Nadać trust wszystkim klientom|To otwiera drogę nielegalnym serwerom.','Zwiększyć metrykę OSPF|Problem jest na granicy zaufania DHCP.','Wyłączyć maskę podsieci|Maska nie jest takim przełącznikiem konfiguracji.'],'Rozpoznanie kierunku odpowiedzi serwera pozwala naprawić konfigurację bez znoszenia całej ochrony.')
c('Pełne wdrożenie snooping','Włącz snooping dla VLAN 50. G1/0/24 to zweryfikowany uplink serwera; inne porty pozostają untrusted.','SW(config)# ip dhcp {{b0}}\nSW(config)# ip dhcp snooping vlan {{b1}}\nSW(config)# interface GigabitEthernet1/0/24\nSW(config-if)# ip dhcp snooping {{b2}}',['snooping','50','trust'],'Najpierw określ zakres VLAN oraz granicę zaufania, a potem weryfikuj przydzielanie adresów.')
c('Port klienta po zmianie roli','Na G1/0/8 cofnij trust, ustaw 10 pps i po odnowieniu DHCP sprawdź binding.','SW(config-if)# no ip dhcp snooping {{b0}}\nSW(config-if)# ip dhcp snooping limit rate {{b1}}\nSW(config-if)# end\nSW# show ip dhcp snooping {{b2}}',['trust','10','binding'],'Niski limit należy dobierać do ruchu danego portu; nie kopiować go bezmyślnie na agregujący uplink.')
q('Opcja 82','Po wdrożeniu snooping serwer odrzuca żądania zawierające opcję 82. Co sprawdzić?','Politykę serwera i obsługę informacji relay/option 82',['Tylko kolor diody portu|Link up nie rozstrzyga obsługi opcji DHCP.','Wartość router ID BGP|Nie steruje formatem żądania DHCP.','Czy klient zna numer AS|Klient DHCP nie musi znać AS.'],'Opcja 82 niesie informacje o punkcie przyłączenia; zgodność polityk należy sprawdzić przed jej wyłączaniem.')
c('Dwa wejścia serwera','Snooping działa dla VLAN 60. G1/0/23 i 24 są zweryfikowanymi drogami legalnych odpowiedzi. Oznacz oba i pokaż stan snooping.','SW(config)# interface GigabitEthernet1/0/23\nSW(config-if)# ip dhcp snooping {{b0}}\nSW(config-if)# exit\nSW(config)# interface GigabitEthernet1/0/24\nSW(config-if)# ip dhcp snooping {{b1}}\nSW(config-if)# end\nSW# show ip dhcp {{b2}}',['trust','trust','snooping'],'Zaufanie musi obejmować każdą legalną drogę wejścia odpowiedzi serwera.')
c('Kontrolowane wycofanie','Wyłącz snooping tylko w VLAN 70, cofnij niepotrzebny trust na G1/0/7 i pokaż stan funkcji.','SW(config)# no ip dhcp snooping vlan {{b0}}\nSW(config)# interface GigabitEthernet1/0/7\nSW(config-if)# no ip dhcp snooping {{b1}}\nSW(config-if)# end\nSW# show ip dhcp {{b2}}',['70','trust','snooping'],'Wycofanie zakresu i pozostałe ustawienia interfejsów należy rozpatrywać osobno.')
end()
start('dai','Dynamic ARP Inspection','5.7',['https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst3650/software/release/16-12/configuration_guide/sec/b_1612_sec_3650_cg/configuring_dynamic_arp_inspection.html','https://www.cisco.com/c/en/us/support/docs/switches/lan-switch-software/222274-troubleshoot-dynamic-arp-inspection-dai.html'])
q('Fałszywe ARP','Jaką informację próbuje weryfikować DAI?','Poprawność powiązania IPv4–MAC w komunikatach ARP',['Podpis certyfikatu HTTPS|DAI nie analizuje certyfikatów TLS.','Każdą trasę IPv6|IPv6 nie używa ARP.','Numer sekwencji TCP|To nie pole protokołu ARP.'],'DAI pomaga ograniczać zatruwanie cache ARP przez fałszywe powiązania.')
c('DAI dla VLAN','Włącz Dynamic ARP Inspection w VLAN 10. Baza legalnych klientów jest przygotowana.','SW(config)# ip arp inspection vlan {{b0}}',['10'],'DAI uruchamia się dla wskazanych VLAN-ów.')
c('Zaufanie ARP','Na zweryfikowanym łączu między kontrolowanymi przełącznikami ustaw zaufanie DAI.','SW(config-if)# ip arp inspection {{b0}}',['trust'],'Ruch z interfejsu trusted omija standardową kontrolę DAI; zaufanie wymaga uzasadnienia.')
q('Baza odniesienia DAI','Skąd DAI zwykle czerpie dynamiczne powiązania klientów DHCP?','Z bazy DHCP Snooping',['Z nazwy hosta w DNS|Nazwa DNS nie potwierdza adresu MAC.','Z tablicy tras BGP|BGP nie przydziela klientom adresów MAC.','Z numerów VLAN w SSID|Samo SSID nie zawiera wiarygodnych dzierżaw.'],'DAI korzysta z bindingów nauczonych przez snooping, a hosty statyczne wymagają osobnego podejścia.')
c('Cofnięcie zaufania ARP','Port po zmianie podłączono do użytkownika. Cofnij zaufanie DAI.','SW(config-if)# no ip arp inspection {{b0}}',['trust'],'Dostęp użytkownika powinien podlegać inspekcji zgodnie z przyjętą polityką.')
c('Liczniki inspekcji','Wyświetl statystyki DAI.','SW# show ip arp inspection {{b0}}',['statistics'],'Liczniki pomagają ocenić, czy pakiety są przepuszczane lub odrzucane.')
q('Dwa różne trust','Czy ip dhcp snooping trust automatycznie oznacza trust dla DAI?','Nie, to odrębne ustawienia',['Tak, każde trust włącza wszystkie zaufania|Granice zaufania należą do konkretnych funkcji.','Tak, ale tylko dla VLAN 1|Nie istnieje taka ogólna reguła VLAN 1.','Nie, bo DAI nie obsługuje trusted|DAI ma własny stan trusted interfejsu.'],'Zaufanie DHCP i zaufanie ARP konfiguruje się niezależnie.')
c('Zakres i uplink DAI','Włącz DAI dla VLAN-ów 10,20 i ustaw trust na sprawdzonym uplinku.','SW(config)# ip arp inspection vlan {{b0}}\nSW(config)# interface GigabitEthernet1/0/24\nSW(config-if)# ip arp inspection {{b1}}',['10,20','trust'],'Lista VLAN-ów i ustawienie interfejsu wspólnie określają miejsce kontroli.')
c('Sprawdź dane wejściowe','Pokaż bazę DHCP Snooping, a następnie statystyki DAI.','SW# show ip dhcp snooping {{b0}}\nSW# show ip arp inspection {{b1}}',['binding','statistics'],'Samo rośnięcie liczników drop nie wyjaśnia przyczyny bez sprawdzenia oczekiwanych powiązań.')
q('Statyczna drukarka','Drukarka ma stałe IP i po włączeniu DAI jej ARP jest odrzucane. Brakuje bindingu DHCP. Jaki kierunek rozwiązania jest właściwy?','Zweryfikowane statyczne powiązanie przez ARP ACL zgodnie z platformą',['Trust na wszystkich portach użytkowników|To wyłącza kontrolę na całym brzegu.','Zmiana hasła SSH drukarki|Nie dostarcza powiązania do DAI.','Włączenie IPv6 w OSPFv2|To nie rozwiązuje kontroli ARP IPv4.'],'Hosty statyczne należy uwzględnić w projekcie inspekcji; brak DHCP nie czyni ich automatycznie nielegalnymi.')
c('Zaufanie odwołane, kontrola','Cofnij trust DAI na bieżącym porcie i wyświetl statystyki.','SW(config-if)# no ip arp inspection {{b0}}\nSW(config-if)# end\nSW# show ip arp inspection {{b1}}',['trust','statistics'],'Po zmianie granicy zaufania obserwuj odrzucenia i poprawne działanie klientów.')
c('Wyłączenie jednego zakresu','Wyłącz DAI w VLAN 30 i pokaż statystyki pozostałej konfiguracji.','SW(config)# no ip arp inspection vlan {{b0}}\nSW(config)# end\nSW# show ip arp inspection {{b1}}',['30','statistics'],'Wyłączenie jednego VLAN-u nie musi wyłączać inspekcji w pozostałych.')
q('Pusta baza po restarcie','Po restarcie switcha baza snooping jest pusta, a klienci mają ważne dzierżawy. DAI odrzuca ich ARP. Co sprawdzić?','Odtwarzanie bazy snooping i sposób ponownego nauczenia legalnych dzierżaw',['Wyłącznie priorytet STP|STP nie odtwarza powiązań dzierżaw.','Czy ARP działa na TCP 443|ARP nie korzysta z portów TCP.','Czy nazwa VLAN ma duże litery|Nazwa nie odtwarza bindingów.'],'Trwałość i odbudowa bazy to element projektu ochrony, nie tylko same komendy włączające.')
c('Snooping plus DAI','Włącz snooping globalnie i dla VLAN 80, następnie DAI dla tego samego VLAN-u. Trust na poprawnych uplinkach już ustawiono.','SW(config)# ip dhcp {{b0}}\nSW(config)# ip dhcp snooping vlan {{b1}}\nSW(config)# ip arp inspection vlan {{b2}}',['snooping','80','80'],'DAI wymaga wiarygodnych powiązań; przygotowanie bazy i wyjątków poprzedza wdrożenie.')
c('Dwie granice zaufania','Bieżący uplink jest zweryfikowany dla DHCP i ARP. Ustaw oba zaufania, a następnie pokaż statystyki DAI.','SW(config-if)# ip dhcp snooping {{b0}}\nSW(config-if)# ip arp inspection {{b1}}\nSW(config-if)# end\nSW# show ip arp inspection {{b2}}',['trust','trust','statistics'],'Oba polecenia mają inny zakres działania mimo tego samego słowa trust.')
q('Czy DAI filtruje IPv6?','Czy samo DAI w VLAN 90 zabezpiecza komunikaty Neighbor Discovery IPv6?','Nie, ND wymaga mechanizmów właściwych IPv6',['Tak, ARP i ND to ten sam protokół|ND korzysta z ICMPv6, a nie ARP.','Tak, jeżeli VLAN jest trunk|Tryb portu nie zmienia protokołu inspekcji.','Tak, jeśli MAC ma 48 bitów|Długość MAC nie nadaje DAI obsługi ND.'],'DAI dotyczy ARP IPv4; nie należy utożsamiać go z ochroną całego stosu IP.')
c('Port klienta bez wyjątków','Na porcie klienta cofnij oba trusty i pokaż bazę snooping.','SW(config-if)# no ip dhcp snooping {{b0}}\nSW(config-if)# no ip arp inspection {{b1}}\nSW(config-if)# end\nSW# show ip dhcp snooping {{b2}}',['trust','trust','binding'],'Cofnięcie tylko jednego trust pozostawia drugą granicę zaufania bez zmiany.')
c('Walidacja źródłowego MAC','W labie włącz DAI dla VLAN 100, dodatkową walidację src-mac i pokaż statystyki. Baza i uplinki są przygotowane.','SW(config)# ip arp inspection vlan {{b0}}\nSW(config)# ip arp inspection validate {{b1}}\nSW(config)# end\nSW# show ip arp inspection {{b2}}',['100','src-mac','statistics'],'src-mac porównuje MAC źródła ramki Ethernet z MAC nadawcy w ARP. Dodatkowe walidacje wymagają przeglądu zgodności.')
end()
